// G2 - SOMENTE LEITURA. Recebe uma cópia do msg.payload do "s7 in" da aba PROCESSO
// (via link) e guarda os 14 sinais booleanos do Processo com o horário da observação.
// Não envia nada para o CLP e não devolve mensagem (return null).
const CAMPOS = ["aguardando", "emergencia", "manual", "ocupado", "cancelOP", "finishOP", "startOP", "comutadorAutomatico", "condicaoIniciar", "emergenciaAtivada", "homeGiro", "homeVertical", "servoGiro", "servoVertical"];
const p = msg.payload;
if (p === null || typeof p !== 'object' || Array.isArray(p)) {
    node.status({ fill: 'red', shape: 'ring', text: 'payload não é objeto' });
    return null;
}
const cache = global.get('g2_n2_cache_leitura') || {};
const agora = Date.now();
let recebidos = 0;
for (const campo of CAMPOS) {
    if (Object.prototype.hasOwnProperty.call(p, campo) && typeof p[campo] === 'boolean') {
        cache[campo] = { valor: p[campo], observadoEm: agora };
        recebidos++;
    }
}
if (recebidos > 0) {
    global.set('g2_n2_cache_leitura', cache);
    node.status({ fill: 'green', shape: 'dot', text: recebidos + '/14 sinais às ' + new Date(agora).toLocaleTimeString() });
} else {
    // Ajuda a diagnosticar nomes diferentes das variáveis S7.
    node.status({ fill: 'yellow', shape: 'ring', text: 'nenhum dos 14 campos; chaves: ' + Object.keys(p).slice(0, 4).join(',') });
}
return null;

// G2 - SOMENTE LEITURA. Responde GET /api/g2/processo/telemetria com os sinais
// observados nos últimos 3 s. 200 = pelo menos um sinal recente; 503 = nenhum.
// Nunca renova horário: cada sinal sai com o instante em que foi observado.
const CAMPOS = ["aguardando", "emergencia", "manual", "ocupado", "cancelOP", "finishOP", "startOP", "comutadorAutomatico", "condicaoIniciar", "emergenciaAtivada", "homeGiro", "homeVertical", "servoGiro", "servoVertical"];
const VALIDADE_MS = 3000;
const cache = global.get('g2_n2_cache_leitura') || {};
const agora = Date.now();
const sinais = {};
const observadosEm = {};
for (const campo of CAMPOS) {
    const item = cache[campo];
    if (!item || typeof item.valor !== 'boolean' || typeof item.observadoEm !== 'number' || !isFinite(item.observadoEm)) continue;
    const idade = agora - item.observadoEm;
    if (idade < 0 || idade > VALIDADE_MS) continue;
    sinais[campo] = item.valor;
    observadosEm[campo] = new Date(item.observadoEm).toISOString();
}
const temDados = Object.keys(sinais).length > 0;
msg.statusCode = temDados ? 200 : 503;
msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
msg.payload = {
    status: temDados ? 'leitura_parcial' : 'sem_dados_recentes',
    estacao: 'PROCESSO',
    timestampConsulta: new Date(agora).toISOString(),
    dadosValidos: temDados,
    sinais,
    observadosEm
};
node.status({ fill: temDados ? 'green' : 'grey', shape: 'dot', text: msg.statusCode + ' · ' + Object.keys(sinais).length + '/14' });
return msg;
